-- Sincronização de categorias — Revolut da Joana
-- gerado por scripts/gerar_import_cgd_joana.py --modo categorias
-- 2859 linhas do Excel com categoria definida (212 ficaram de fora por estar 'A confirmar' ou vazias).
--
-- Casa cada linha do Excel com uma transação já importada por
-- data + valor + tipo + descrição normalizada como PREFIXO (não por
-- fingerprint: a descrição gravada no banco tem um sufixo
-- '[Categoria original Revolut: ...]' que a planilha não tem — conferido
-- em produção nesta sessão, 2026-08-06). Calculado em SQL puro contra as
-- duas contas Revolut da Joana — não precisa do UUID delas de antemão.
--
-- ===========================================================================
-- PASSO 1 — rode só o SELECT abaixo primeiro e leia o resultado. Só as linhas
-- 'sem correspondência' e 'correspondência ambígua' NÃO são tocadas pelo
-- UPDATE do passo 2. As demais categorias diferentes da atual SÃO
-- atualizadas, inclusive as já revisadas manualmente — decisão explícita do
-- Gabriel em 2026-08-06 (o padrão original só tocava needs_review=true; ele
-- preferiu aplicar tudo de uma vez depois de ver que o balde 'já revisada'
-- tinha 1.422 linhas).
-- ===========================================================================

with joana_revolut as (
  select a.id from public.accounts a
  join public.profiles p on p.id = a.owner_profile_id
  where p.display_name ilike 'joana%' and public.normalize_description(a.name) like '%revolut%'
),
